# Source: https://github.com/sat-group/cfg-enum/blob/permissive/benchmarks/simple-de-lock.ivy

type node

relation message(Src: node, Dst: node)
relation has_lock(N: node)

individual start_node: node

after init {
	message(Src, Dst) := false;
	has_lock(X) := X = start_node;
}

action send(src: node, dst: node) = {
    assume has_lock(src);
    message(src, dst) := true;
    has_lock(src) := false;
}

action recv(src: node, dst: node) = {
    assume message(src, dst);
    message(src, dst) := false;
    has_lock(dst) := true;
}

export send
export recv

invariant [safety_1] X ~= Y -> ~(has_lock(X) & has_lock(Y))

invariant ~(has_lock(X) & message(Y,Z))
invariant ~(message(X,Y) & message(Z,W) & X ~= Z)
invariant has_lock(X) | exists Y. message(Y,X) | X = start_node
invariant ~(has_lock(X) & X ~= start_node & exists Y. message(Y,X))
invariant has_lock(X) -> X = start_node

