# Source: https://github.com/microsoft/ivy/blob/master/examples/ivy/toy_consensus.ivy 

type node
type value
type quorum

relation member(N:node, Q:quorum)
axiom forall Q1:quorum, Q2:quorum. exists N:node. member(N, Q1) & member(N, Q2)

relation vote(N:node, V:value)
relation decision(V:value)

relation didNotVote(N:node) = forall V. ~vote(N, V)
relation chosenAt(Q:quorum, V:value) = forall N. member(N, Q) -> vote(N, V)

after init  {
    vote(N,V) := false ;
    decision(V) := false;
}

action cast_vote(n:node, v:value) = {
    assume didNotVote(n);
    vote(n, v) := true
}

action decide(v:value, q:quorum) = {
    assume chosenAt(q, v);
    decision(v) := true
}

export cast_vote
export decide

# safety property:
invariant [safety_1] decision(V1) & decision(V2) -> V1 = V2

invariant ~(decision(V1) & decision(V2) & V1 ~= V2)
invariant decision(V) -> exists Q:quorum. chosenAt(Q, V)
invariant chosenAt(Q1, V1) & chosenAt(Q2, V2) & V1 ~= V2 -> exists N:node. member(N, Q1) & member(N, Q2) & vote(N, V1) & vote(N, V2)
invariant ~(vote(N, V1) & vote(N, V2) & V1 ~= V2)

