after init  {
    semaphore(Y) := true ;
    link(X, Y) := false;
}

type client

type server

relation link(X: client, Y: server)
relation semaphore(X: server)


action connect(c: client, s: server) = {
    require semaphore(s);
    link(c, s) := true;
    semaphore(s) := false;
}

action disconnect(c: client, s: server) = {
    require link(c, s);
    link(c, s) := false;
    semaphore(s) := true;
}


export connect

export disconnect

invariant [safety_unique] forall C1, C2 : client, S: server. link(C1, S) & link(C2, S) -> C1 = C2

invariant forall S : server. semaphore(S) -> ~link(C, S)
invariant forall C : client, S : server. link(C, S) -> ~semaphore(S)
invariant forall C1, C2 : client, S : server. link(C1, S) & semaphore(S) -> C1 = C2
invariant forall S : server. semaphore(S) | exists C : client. link(C, S)
invariant forall C1, C2 : client, S : server. link(C1, S) & link(C2, S) -> C1 = C2

