relation leader(N:node)
relation pending(I:id, N:node)
relation sent(N:node)

after init  {
	leader(N) := false;
	pending(V, N) := false;
	sent(N) := false;
}

action send(n: node, next: node) = {
  require (forall Z. (Z ~= n & Z ~= next) -> btw(n, next, Z));

  pending(idn(n), next) := true;
  sent(n) := true;
}

action recv(v:id, n:node, next:node) = {
  require (forall Z. (Z ~= n & Z ~= next) -> btw(n, next, Z));
  require pending(v, n);

  pending(v, n) := *;	# message may or may not be removed, nothing is sent
  if v = idn(n) {
    leader(n) := true;
  }
  else {
    if le(idn(n), v) {
      pending(v, next) := true;	# forward v to next
    }
  }
}

export send
export recv

invariant [safety_not_dead] (exists L. leader(L)) | (exists M,N. pending(M, N)) | (exists N. ~sent(N))

invariant ~pending(V, N) | sent(N)
invariant ~pending(V, N) | le(idn(N), V) | V = idn(N)
invariant ~pending(V, N) | (exists M. pending(V, M))
invariant ~sent(N) | (exists V, M. pending(V, M)) | leader(N) | (exists M. M ~= N & sent(M))
invariant ~leader(N) | (exists M. sent(M))
invariant ~leader(N) | (exists V, M. pending(V, M)) | (exists M. M ~= N & sent(M))
invariant ~sent(N) | (exists M. M ~= N & sent(M)) | (exists V, M. pending(V, M)) | leader(N)
invariant ~leader(N) | (exists M. M ~= N & sent(M)) | (exists V, M. pending(V, M))
invariant ~pending(V, N) | ~pending(V, M) | N = M
invariant ~pending(V, N) | ~pending(W, N) | V = W
invariant ~pending(V, N) | ~sent(M) | M = N | (exists U, K. pending(U, K))
invariant ~leader(N) | ~sent(M) | M = N | (exists U, K. pending(U, K))
invariant ~sent(N) | ~sent(M) | N = M | (exists U, K. pending(U, K)) | leader(N)

