module total_order(r) = {
    axiom r(X,X)                        # Reflexivity
    axiom r(X, Y) & r(Y, Z) -> r(X, Z)  # Transitivity
    axiom r(X, Y) & r(Y, X) -> X = Y    # Anti-symmetry
    axiom r(X, Y) | r(Y, X)             # Totality
}


################################################################################
#
# Types, relations and functions describing state of the network
#
################################################################################

type round
type value
type quorum_1
type quorum_2
type node

relation le(X:round, Y:round)
instantiate total_order(le)

individual negone:round
axiom le(negone, X)
individual max:round
axiom le(X, max)

relation member_1(N:node, Q:quorum_1)
relation member_2(N:node, Q:quorum_2)
axiom forall Q1:quorum_1, Q2:quorum_2. exists N:node. member_1(N, Q1) & member_2(N, Q2)

relation one_a(R:round)
relation one_b_max_vote(N:node, R1:round, R2:round, V:value)
relation one_b(N:node, R:round) # := exists RMAX, V. one_b_max_vote(N,R,RMAX,V)
relation left_rnd(N:node, R:round) # := exists R2, RMAX, V. ~le(R2,R) & one_b_max_vote(N,R,RMAX,V)
relation proposal(R:round, V:value) # 2a
relation vote(N:node, R:round, V:value) # 2b
relation decision(N:node, R:round, V:value) # got 2b from a quorum_2

# Definitions for ivy to vmt
relation chosenAt(R:round, V:value) = exists Q:quorum_2. forall N. member_2(N, Q) -> vote(N, R, V)
relation showsSafeAtPaxos(Qin:quorum_1, Rin:round, Vin:value) = 
(
	(forall N. member_1(N, Qin) -> one_b(N,Rin)) &
	(	exists MAXRin. (MAXRin = negone & forall N:node,MAXR:round,V:value. ~(member_1(N, Qin) & ~le(Rin,MAXR) & vote(N,MAXR,V))) | 
		(MAXRin ~= negone &
			(exists N:node. member_1(N, Qin) & ~le(Rin,MAXRin) & vote(N,MAXRin,Vin)) &
			(forall N:node,MAXR:round,V:value. (member_1(N, Qin) & ~le(Rin,MAXR) & vote(N,MAXR,V)) -> le(MAXR,MAXRin))
		)
	)
)
relation isSafeAtPaxos(R:round, V:value) = exists Q:quorum_1 . showsSafeAtPaxos(Q, R, V)


after init {
	one_a(R) := false;
	one_b_max_vote(N,R1,R2,V) := false;
	one_b(N,R) := false;
	left_rnd(N,R) := false;
	proposal(R,V) := false;
	vote(N,R,V) := false;
	decision(N,R,V) := false;
}

action send_1a = {
    # a proposer selects a round and sends a message asking nodes to join the round
    local r:round {
        assume r ~= negone;
        one_a(r) := true
    }
}


action join_round = {
    # receive 1a and answer with 1b
    local n:node, r:round {
        assume r ~= negone;
        assume one_a(r);
        assume ~left_rnd(n,r);

        local maxr:round, v:value {
            # find the maximal vote in a round less than r
            assume ((maxr = negone & forall MAXR:round,V:value. ~(~le(r,MAXR) & vote(n,MAXR,V))) |
                    (maxr ~= negone & ~le(r,maxr) & vote(n,maxr,v) &
                    (forall MAXR:round,V:value. (~le(r,MAXR) & vote(n,MAXR,V)) -> le(MAXR,maxr))
                   ));
            # send the 1b message
            one_b_max_vote(n,r,maxr,v) := true;
            one_b(n,r) := true;
            left_rnd(n,R) := left_rnd(n,R) | ~le(r,R)
        }
    }
}


action propose = {
    # receive a quorum_1 of 1b's and send a 2a (proposal)
    local r:round, v:value {
        assume r ~= negone;
        assume ~proposal(r,V);
		assume isSafeAtPaxos(r, v);

		proposal(r, v) := true
    }
}

action cast_vote = {
    # receive a 2a and send 2b
    local n:node, v:value, r:round {
        assume r ~= negone;
        assume ~left_rnd(n,r);
        assume proposal(r, v);
        vote(n, r, v) := true
    }
}

action decide = {
    # get 2b from a quorum_2
    local n:node, r:round, v:value {
        assume r ~= negone;
        assume chosenAt(r, v);
        decision(n, r, v) := true
    }
}

export send_1a
export join_round
export propose
export cast_vote
export decide

# safety property:
invariant [safety_1] (    decision(N1,R1,V1) &
    decision(N2,R2,V2)
) -> V1 = V2

invariant [safety_2] decision(N,R,V) -> chosenAt(R,V)
invariant [safety_3] chosenAt(R,V) -> proposal(R,V)
invariant [safety_4] vote(N,R,V) -> proposal(R,V)
invariant [safety_5] vote(N,R,V) & vote(N,R,W) -> V = W
invariant [safety_6] proposal(R,V) & proposal(R,W) -> V = W
invariant [safety_7] vote(N,R,V) & vote(N,S,W) & ~le(R,S) -> ~le(S,R)
invariant [safety_8] vote(N,R,V) -> ~left_rnd(N,R)
invariant [safety_9] one_b(N,R) -> ~left_rnd(N,R)
invariant [safety_10] one_b_max_vote(N,R,MAX,V) -> vote(N,MAX,V) | MAX = negone
invariant [safety_11] one_b_max_vote(N,R,MAX,V) & MAX ~= negone -> ~le(R,MAX)
invariant [safety_12] showsSafeAtPaxos(Q,R,V) -> forall N. member_1(N,Q) -> one_b(N,R)
invariant [safety_13] showsSafeAtPaxos(Q,R,V) & MAX ~= negone -> exists N. member_1(N,Q) & ~le(R,MAX) & vote(N,MAX,V)
invariant [safety_14] showsSafeAtPaxos(Q,R,V) -> forall N,MAXR,W. (member_1(N,Q) & ~le(R,MAXR) & vote(N,MAXR,W)) -> le(MAXR,MAX)
invariant [safety_15] vote(N,R,V) -> exists MAX. (MAX = negone & forall S,W. ~(~le(R,S) & vote(N,S,W))) | (MAX ~= negone & ~le(R,MAX) & vote(N,MAX,V) & (forall S,W. (~le(R,S) & vote(N,S,W)) -> le(S,MAX)))
invariant [safety_16] proposal(R,V) -> exists Q. showsSafeAtPaxos(Q,R,V)
invariant [safety_17] chosenAt(R,V) & chosenAt(R,W) -> V = W
invariant [safety_18] ~one_a(R)

