axiom forall Q1:quorum, Q2:quorum. exists N:node. member(N, Q1) & member(N, Q2)

relation one_a(R:round)
relation one_b_max_vote(N:node, R1:round, R2:round, V:value)
relation one_b(N:node, R:round) # := exists RMAX, V. one_b_max_vote(N,R,RMAX,V)
relation left_rnd(N:node, R:round) # := exists R2, RMAX, V. ~le(R2,R) & one_b_max_vote(N,R,RMAX,V)
relation proposal(R:round, V:value) # 2a
relation vote(N:node, R:round, V:value) # 2b
relation decision(N:node, R:round, V:value) # got 2b from a quorum

# Definitions for ivy to vmt
relation chosenAt(R:round, V:value) = exists Q. forall N. member(N, Q) -> vote(N, R, V)
relation showsSafeAtPaxos(Qin:quorum, Rin:round, Vin:value) = 
(
	(forall N. member(N, Qin) -> one_b(N,Rin)) &
	(	exists MAXRin. (MAXRin = negone & forall N:node,MAXR:round,V:value. ~(member(N, Qin) & ~le(Rin,MAXR) & vote(N,MAXR,V))) | 
		(MAXRin ~= negone &
			(exists N:node. member(N, Qin) & ~le(Rin,MAXRin) & vote(N,MAXRin,Vin)) &
			(forall N:node,MAXR:round,V:value. (member(N, Qin) & ~le(Rin,MAXR) & vote(N,MAXR,V)) -> le(MAXR,MAXRin))
		)
	)
)
relation isSafeAtPaxos(R:round, V:value) = exists Q:quorum . showsSafeAtPaxos(Q, R, V)


after init {
	one_a(R) := false;
	one_b_max_vote(N,R1,R2,V) := false;
	one_b(N,R) := false;
	left_rnd(N,R) := false;
	proposal(R,V) := false;
	vote(N,R,V) := false;
	decision(N,R,V) := false;
}

action send_1a = {
    # a proposer selects a round and sends a message asking nodes to join the round
    local r:round {
        assume r ~= negone;
        one_a(r) := true
    }
}


action join_round = {
    # receive 1a and answer with 1b
    local n:node, r:round {
        assume r ~= negone;
        assume one_a(r);
        assume ~left_rnd(n,r);

        local maxr:round, v:value {
            # find the maximal vote in a round less than r
            assume ((maxr = negone & forall MAXR:round,V:value. ~(~le(r,MAXR) & vote(n,MAXR,V))) |
                    (maxr ~= negone & ~le(r,maxr) & vote(n,maxr,v) &
                    (forall MAXR:round,V:value. (~le(r,MAXR) & vote(n,MAXR,V)) -> le(MAXR,maxr))
                   ));
            # send the 1b message
            one_b_max_vote(n,r,maxr,v) := true;
            one_b(n,r) := true;
            left_rnd(n,R) := left_rnd(n,R) | ~le(r,R)
        }
    }
}


action propose = {
    # receive a quorum of 1b's and send a 2a (proposal)
    local r:round, v:value {
        assume r ~= negone;
        assume ~proposal(r,V);
		assume isSafeAtPaxos(r, v);

		proposal(r, v) := true
    }
}

action cast_vote = {
    # receive a 2a and send 2b
    local n:node, v:value, r:round {
        assume r ~= negone;
        assume ~left_rnd(n,r);
        assume proposal(r, v);
        vote(n, r, v) := true
    }
}

action decide = {
    # get 2b from a quorum
    local n:node, r:round, v:value {
        assume r ~= negone;
        assume chosenAt(r, v);
        decision(n, r, v) := true
    }
}

export send_1a
export join_round
export propose
export cast_vote
export decide

# safety property:
invariant [safety_1] (    decision(N1,R1,V1) &
    decision(N2,R2,V2)
) -> V1 = V2

invariant decision(N,R,V1) & decision(N,R,V2) -> V1 = V2
invariant decision(N,R,V) -> chosenAt(R,V)
invariant chosenAt(R,V) -> exists Q. forall N. member(N,Q) -> vote(N,R,V)
invariant vote(N,R,V) -> proposal(R,V)
invariant vote(N,R,V) -> ~left_rnd(N,R)
invariant proposal(R,V) -> isSafeAtPaxos(R,V)
invariant isSafeAtPaxos(R,V) -> exists Q. showsSafeAtPaxos(Q,R,V)
invariant showsSafeAtPaxos(Q,R,V) -> (forall N. member(N,Q) -> one_b(N,R))
invariant showsSafeAtPaxos(Q,R,V) -> (exists MAXR. (MAXR = negone & forall N,MAXR2,V2. ~(member(N,Q) & ~le(R,MAXR2) & vote(N,MAXR2,V2))) | (MAXR ~= negone & (exists N. member(N,Q) & ~le(R,MAXR) & vote(N,MAXR,V)) & (forall N,MAXR2,V2. (member(N,Q) & ~le(R,MAXR2) & vote(N,MAXR2,V2)) -> le(MAXR2,MAXR))))
invariant one_b(N,R) -> one_a(R)
invariant one_b(N,R) -> exists MAXR,V. one_b_max_vote(N,R,MAXR,V)
invariant one_b_max_vote(N,R,MAXR,V) -> (MAXR = negone & forall MAXR2,V2. ~(~le(R,MAXR2) & vote(N,MAXR2,V2))) | (MAXR ~= negone & ~le(R,MAXR) & vote(N,MAXR,V) & (forall MAXR2,V2. (~le(R,MAXR2) & vote(N,MAXR2,V2)) -> le(MAXR2,MAXR)))
invariant one_b_max_vote(N,R,MAXR,V) -> one_b(N,R)
invariant left_rnd(N,R) -> exists R2,MAXR,V. ~le(R2,R) & one_b_max_vote(N,R2,MAXR,V)
invariant one_b_max_vote(N,R,MAXR,V) -> left_rnd(N,R2) | le(R2,R)
invariant vote(N,R,V) & vote(N,R,V2) -> V = V2
invariant proposal(R,V) & proposal(R,V2) -> V = V2
invariant one_b_max_vote(N,R,MAXR,V) & one_b_max_vote(N,R,MAXR2,V2) -> MAXR = MAXR2 & V = V2
invariant one_b(N,R) & one_b(N,R2) & ~le(R2,R) -> left_rnd(N,R)
invariant ~le(R2,R) & left_rnd(N,R) -> ~one_b(N,R2)
invariant vote(N,R,V) & ~le(R,R2) & vote(N,R2,V2) -> le(R2,R)
invariant chosenAt(R,V) & chosenAt(R,V2) -> V = V2
invariant forall R,V1,V2. chosenAt(R,V1) & chosenAt(R,V2) -> V1 = V2
invariant forall R,V1,V2. proposal(R,V1) & proposal(R,V2) -> V1 = V2
invariant forall N,R,V1,V2. vote(N,R,V1) & vote(N,R,V2) -> V1 = V2
invariant forall N,R,MAXR1,V1,MAXR2,V2. one_b_max_vote(N,R,MAXR1,V1) & one_b_max_vote(N,R,MAXR2,V2) -> MAXR1 = MAXR2 & V1 = V2
invariant forall N,R1,R2. one_b(N,R1) & one_b(N,R2) & ~le(R2,R1) -> left_rnd(N,R1)
invariant forall N,R1,R2. ~le(R2,R1) & left_rnd(N,R1) -> ~one_b(N,R2)
invariant forall N,R1,R2,V1,V2. vote(N,R1,V1) & ~le(R1,R2) & vote(N,R2,V2) -> le(R2,R1)
invariant forall R,V. chosenAt(R,V) -> exists Q. forall N. member(N,Q) -> vote(N,R,V)
invariant forall R,V. proposal(R,V) -> isSafeAtPaxos(R,V)
invariant forall R,V. isSafeAtPaxos(R,V) -> exists Q. showsSafeAtPaxos(Q,R,V)
invariant forall Q,R,V. showsSafeAtPaxos(Q,R,V) -> (forall N. member(N,Q) -> one_b(N,R))
invariant forall Q,R,V. showsSafeAtPaxos(Q,R,V) -> (exists MAXR. (MAXR = negone & forall N,MAXR2,V2. ~(member(N,Q) & ~le(R,MAXR2) & vote(N,MAXR2,V2))) | (MAXR ~= negone & (exists N. member(N,Q) & ~le(R,MAXR) & vote(N,MAXR,V)) & (forall N,MAXR2,V2. (member(N,Q) & ~le(R,MAXR2) & vote(N,MAXR2,V2)) -> le(MAXR2,MAXR))))
invariant forall N,R. one_b(N,R) -> one_a(R)
invariant forall N,R. one_b(N,R) -> exists MAXR,V. one_b_max_vote(N,R,MAXR,V)
invariant forall N,R,MAXR,V. one_b_max_vote(N,R,MAXR,V) -> (MAXR = negone & forall MAXR2,V2. ~(~le(R,MAXR2) & vote(N,MAXR2,V2))) | (MAXR ~= negone & ~le(R,MAXR) & vote(N,MAXR,V) & (forall MAXR2,V2. (~le(R,MAXR2) & vote(N,MAXR2,V2)) -> le(MAXR2,MAXR)))
invariant forall N,R,MAXR,V. one_b_max_vote(N,R,MAXR,V) -> one_b(N,R)
invariant forall N,R. left_rnd(N,R) -> exists R2,MAXR,V. ~le(R2,R) & one_b_max_vote(N,R2,MAXR,V)
invariant forall N,R,MAXR,V,R2. one_b_max_vote(N,R,MAXR,V) -> left_rnd(N,R2) | le(R2,R)
invariant forall N,R1,R2,V1,V2. vote(N,R1,V1) & vote(N,R2,V2) & ~le(R1,R2) & ~le(R2,R1) -> V1 = V2
invariant forall N,R1,R2,V1,V2. vote(N,R1,V1) & vote(N,R2,V2) & ~le(R1,R2) -> le(R2,R1) | V1 = V2
invariant forall N,R1,R2,V1,V2. vote(N,R1,V1) & vote(N,R2,V2) & ~le(R1,R2) -> le(R2,R1) | (exists MAXR. MAXR ~= negone & ~le(R1,MAXR) & vote(N,MAXR,V1) & (forall MAXR2,V3. (~le(R1,MAXR2) & vote(N,MAXR2,V3)) -> le(MAXR2,MAXR)))
invariant forall N,R1,R2,V1,V2. vote(N,R1,V1) & vote(N,R2,V2) & ~le(R1,R2) -> le(R2,R1) | (exists MAXR. MAXR ~= negone & ~le(R1,MAXR) & vote(N,MAXR,V1) & (forall MAXR2,V3. (~le(R1,MAXR2) & vote(N,MAXR2,V3)) -> le(MAXR2,MAXR)) & (exists Q. showsSafeAtPaxos(Q,R1,V1)))
