invariant forall N,R1,R2,V1,V2. vote(N,R1,V1) & vote(N,R2,V2) & ~le(R1,R2) -> le(R2,R1) | (exists MAXR. MAXR ~= negone & ~le(R1,MAXR) & vote(N,MAXR,V1) & (forall MAXR2,V3. (~le(R1,MAXR2) & vote(N,MAXR2,V3)) -> le(MAXR2,MAXR)) & (exists Q. showsSafeAtPaxos(Q,R1,V1)) & (exists Q2. showsSafeAtPaxos(Q2,R2,V2)) & V1 = V2)
invariant forall N,R1,R2,V1,V2. vote(N,R1,V1) & vote(N,R2,V2) & ~le(R1,R2) -> le(R2,R1) | V1 = V2
invariant forall N,R1,R2,V1,V2. vote(N,R1,V1) & vote(N,R2,V2) & ~le(R1,R2) -> le(R2,R1) | (exists MAXR. MAXR ~= negone & ~le(R1,MAXR) & vote(N,MAXR,V1) & (forall MAXR2,V3. (~le(R1,MAXR2) & vote(N,MAXR2,V3)) -> le(MAXR2,MAXR)) & (exists Q. showsSafeAtPaxos(Q,R1,V1)) & (exists Q2. showsSafeAtPaxos(Q2,R2,V2)) & V1 = V2 & (forall N2. member(N2,Q) -> one_b(N2,R1)) & (forall N2. member(N2,Q2) -> one_b(N2,R2)))
