#lang ivy1.7

# An exact specification of the Paxos algorithm, as presented 
# by Lamport at several occasions (like HowToWinATuringAward).

type value
type acceptor
type quorum
type ballot

# A total order helper module
module total_order(r) = {
    axiom r(X, X)                       # Reflexivity
    axiom r(X, Y) & r(Y, Z) -> r(X, Z)  # Transitivity
    axiom r(X, Y) & r(Y, X) -> X = Y    # Anti-symmetry
    axiom r(X, Y) | r(Y, X)             # Totality
}

relation le(X:ballot, Y:ballot)
instantiate total_order(le)
individual negone:ballot
axiom le(negone, X)
individual max:ballot
axiom le(X, max)

individual none:value

relation member(A:acceptor, Q:quorum)
axiom forall Q1, Q2. exists A:acceptor. member(A, Q1) & member(A, Q2)

relation msg_1a(B:ballot)
relation msg_1b(A:acceptor, B:ballot, MBAL:ballot, MVAL:value)
relation msg_2a(B:ballot, V:value)
relation msg_2b(A:acceptor, B:ballot, V:value)

function maxBal(A:acceptor):ballot
function maxVBal(A:acceptor):ballot
function maxVal(A:acceptor):value

# Definitions
relation chosenAt(B:ballot, V:value) = exists Q. forall A. member(A, Q) -> msg_2b(A, B, V)
relation chosen(V:value) = exists B. chosenAt(B, V)
relation showsSafeAt(Q:quorum, B:ballot, V:value) = ((forall A:acceptor. member(A, Q) -> le(B, maxBal(A))) & 
													(exists C:ballot. ~le(B, C) & 
														(C ~= negone -> exists A:acceptor. member(A, Q) & msg_2b(A, C, V)) & 
														(forall D:ballot. (~le(D, C) & ~le(B, D)) -> 
															(forall A:acceptor. member(A, Q) -> (forall Vd:value. ~msg_2b(A, D, Vd))))))
relation isSafeAt(B:ballot, V:value) = exists Q:quorum. showsSafeAt(Q, B, V)

relation showsSafeAtPaxosSimple(Q:quorum, B:ballot, V:value) =
		(	(forall A. member(A, Q) -> exists MBAL, MVAL. msg_1b(A, B, MBAL, MVAL)) & 
		(	(forall A, MBAL, MVAL. ~(member(A, Q) & msg_1b(A, B, MBAL, MVAL) & msg_2b(A, MBAL, MVAL))) |
			(exists MBAL.	(exists A. member(A, Q) & msg_1b(A, B, MBAL, V) & msg_2b(A, MBAL, V)) &
							(forall A, MBAL2, MVAL2. member(A, Q) & msg_1b(A, B, MBAL2, MVAL2) & msg_2b(A, MBAL2, MVAL2) -> le(MBAL2, MBAL)))
		))
relation isSafeAtPaxosSimple(B:ballot, V:value) = exists Q:quorum. showsSafeAtPaxosSimple(Q, B, V)

relation showsSafeAtPaxos(Q:quorum, B:ballot, V:value) =
		(	(forall A. member(A, Q) -> exists MBAL, MVAL. msg_1b(A, B, MBAL, MVAL)) & 
			(	(forall A, MBAL, MVAL. ~(member(A, Q) & msg_1b(A, B, MBAL, MVAL) & MBAL ~= negone)) |
				(exists MBAL.	(exists A. member(A, Q) & msg_1b(A, B, MBAL, V) & (MBAL ~= negone)) &
								(forall A, MBAL2, MVAL2. member(A, Q) & msg_1b(A, B, MBAL2, MVAL2) & (MBAL2 ~= negone) -> le(MBAL2, MBAL)))
		))
relation isSafeAtPaxos(B:ballot, V:value) = exists Q:quorum. showsSafeAtPaxos(Q, B, V)

after init {
    maxBal(A) := negone;
    maxVBal(A) := negone;
    maxVal(A) := none;
    msg_1a(B) := false;
    msg_1b(A, B, MBAL, MVAL) := false;
    msg_2a(B, V) := false;
    msg_2b(A, B, V) := false;
}

action phase_1a(b:ballot) = {
    require b ~= negone;

    msg_1a(b) := true;
}

action phase_1b(a:acceptor, b:ballot) = {
    require b ~= negone;
    require msg_1a(b);
    require ~le(b, maxBal(a));

    maxBal(a) := b;
    msg_1b(a, b, maxVBal(a), maxVal(a)) := true;
}

action phase_2a(b:ballot, v:value) = {
    require b ~= negone;
    require v ~= none;
    require ~(exists V. msg_2a(b, V));
	require isSafeAtPaxos(b, v);

    msg_2a(b, v) := true;
}

action phase_2b(a:acceptor, b:ballot, v:value) = {
    require b ~= negone;
    require v ~= none;
    require msg_2a(b, v);
    require le(maxBal(a), b);

    maxBal(a) := b;
    maxVBal(a) := b;
    maxVal(a) := v;
    msg_2b(a, b, v) := true;
}

export phase_1a
export phase_1b
export phase_2a
export phase_2b

# the safety property
invariant [safety] forall V1, V2. chosen(V1) & chosen(V2) -> (V1 = V2)

invariant forall A:acceptor, B:ballot, V:value. msg_2b(A, B, V) -> le(maxVBal(A), B) & maxVal(A) = V
invariant forall A:acceptor, B:ballot, V:value. msg_2b(A, B, V) -> le(B, maxBal(A))
invariant forall A:acceptor, B:ballot, MBAL:ballot, MVAL:value. msg_1b(A, B, MBAL, MVAL) -> le(MBAL, maxVBal(A)) & maxVal(A) = MVAL
invariant forall A:acceptor, B:ballot, MBAL:ballot, MVAL:value. msg_1b(A, B, MBAL, MVAL) -> le(B, maxBal(A))
invariant forall A:acceptor, B:ballot, V:value. msg_2b(A, B, V) -> (exists Q:quorum. member(A, Q) & showsSafeAtPaxos(Q, B, V))
invariant forall B1:ballot, V1:value, B2:ballot, V2:value. msg_2a(B1, V1) & msg_2a(B2, V2) & B1 ~= B2 -> V1 = V2
invariant forall B:ballot, V:value. msg_2a(B, V) -> isSafeAtPaxos(B, V)
invariant forall A:acceptor, B1:ballot, V1:value, B2:ballot, V2:value. msg_2b(A, B1, V1) & msg_2b(A, B2, V2) -> (B1 = B2 & V1 = V2) | (le(B1, B2) & V1 = V2) | (le(B2, B1) & V1 = V2)
invariant forall A:acceptor, B:ballot, V:value. msg_2b(A, B, V) -> ~le(B, negone)
invariant forall A:acceptor, B:ballot, MBAL:ballot, MVAL:value. msg_1b(A, B, MBAL, MVAL) -> ~le(B, negone)
invariant forall A:acceptor, B:ballot, V:value. msg_2b(A, B, V) -> (forall Q:quorum. showsSafeAtPaxos(Q, B, V) -> member(A, Q))
invariant forall B:ballot, V:value. chosenAt(B, V) -> (forall A:acceptor, B2:ballot, V2:value. msg_2b(A, B2, V2) & le(B, B2) -> V2 = V)
invariant forall B:ballot, V:value. chosenAt(B, V) -> (forall B2:ballot, V2:value. chosenAt(B2, V2) & le(B, B2) -> V2 = V)

