invariant forall Q:quorum, B:ballot, V:value. showsSafeAtPaxosSimple(Q, B, V) -> ((forall A, MBAL, MVAL. ~(member(A, Q) & msg_1b(A, B) & msg_2b(A, MBAL, MVAL))) | (exists MBAL. (exists A. member(A, Q) & msg_1b(A, B) & msg_2b(A, MBAL, V)) & (forall A, MBAL2, MVAL2. member(A, Q) & msg_1b(A, B) & msg_2b(A, MBAL2, MVAL2) -> le(MBAL2, MBAL))))
invariant forall Q:quorum, B:ballot, V:value. showsSafeAtPaxosSimple(Q, B, V) -> (forall A:acceptor, MBAL:ballot, MVAL:value. member(A, Q) & msg_1b(A, B) & msg_2b(A, MBAL, MVAL) -> MVAL = V)
